import java.util.Properties

plugins {
    // Plugins automatically generated by MLGradleWriter.kt
    alias(libs.plugins.android.application)
    alias(libs.plugins.kotlin.compose)
}

// 版本号从 version.properties 读，CI 与本地共用同一数据源。
// 优先级：CI 环境变量 > version.properties > 兜底默认值。
// 详见 .cnb/scripts/resolve-version.sh 顶部注释。
val versionProps = Properties().apply {
    val f = rootProject.file("version.properties")
    if (f.exists()) f.inputStream().use { load(it) }
}
val ciVersionCode = System.getenv("APP_VERSION_CODE")?.toIntOrNull()
val ciVersionName = System.getenv("APP_VERSION_NAME")?.takeIf { it.isNotBlank() }

android {
    namespace = "com.xixin.apkforge"
    compileSdk = 37

    defaultConfig {
        applicationId = "com.xixin.apkforge"
        minSdk = 28
        targetSdk = 34
        versionCode = ciVersionCode
            ?: versionProps.getProperty("VERSION_CODE")?.toIntOrNull()
            ?: 1
        versionName = ciVersionName
            ?: versionProps.getProperty("VERSION_NAME")
            ?: "1.0"

        testInstrumentationRunner = "androidx.test.runner.AndroidJUnitRunner"

        ndk {
            // 只出 arm64-v8a。
            // 理由：① 本地开发机就是 arm64，多打 armeabi-v7a / x86 / x86_64 纯属浪费，
            //        adb install 也快一倍；
            //      ② Compose UI 会传递依赖 androidx.graphics:graphics-path，
            //        带来 libandroidx.graphics.path.so / libdlogbridge.so，
            //        收窄 ABI 后 .so 由 8 个减到 2 个，连带缩小 16KB 页对齐影响面。
            // 上架前若需覆盖 32 位老设备，改为 listOf("armeabi-v7a", "arm64-v8a")。
            abiFilters += "arm64-v8a"
        }
    }

    buildTypes {
        debug {
            // debug 同样只保留 arm64-v8a：本地安装/调试不需要其他 ABI
            ndk {
                abiFilters += "arm64-v8a"
            }
        }
        release {
            // release 如需覆盖 32 位设备，改成：
            //   abiFilters += listOf("armeabi-v7a", "arm64-v8a")
            ndk {
                abiFilters += "arm64-v8a"
            }
        }
    }

    buildFeatures {
        compose = true
    }

    // 压缩 dex 与 .so：6700 万字节的 dex 压缩后约 1800 万（AGP 默认 STORED）。
    // 代价是冷启动要解压；不启用 R8，因为注入测试需要真实的类名与代码形态。
    packaging {
        dex {
            useLegacyPackaging = true
        }
        jniLibs {
            useLegacyPackaging = true
        }
    }

    // 端到端测试会加载 37MB 的真实 APK 并重写 dex，默认堆（512MB）会 OOM。
    // 2048MB 是实测能稳定跑完的下限。
    testOptions {
        unitTests.all {
            it.maxHeapSize = "2048m"
            it.jvmArgs("-XX:MaxMetaspaceSize=512m")
            // 外部验证夹具（InjectArtifactFixture）需要把路径传进测试 JVM。
            // Gradle 不继承环境变量、也不转发 -D，只能显式转发。
            listOf(
                "APKFORGE_TEST_APK",
                "APKFORGE_RELEASE_APK",
                "APKFORGE_FIXTURE_APK",
                "APKFORGE_FIXTURE_OUT",
            ).forEach { k -> System.getenv(k)?.let { v -> it.environment(k, v) } }
        }
    }

    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_21
        targetCompatibility = JavaVersion.VERSION_21
    }
    kotlin {
        jvmToolchain(21)
    }
}

dependencies {
    implementation(libs.androidx.core.ktx)
    implementation(libs.androidx.lifecycle.runtime.ktx)
    implementation(libs.androidx.lifecycle.runtime.compose)
    implementation(libs.androidx.lifecycle.viewmodel.compose)
    implementation(libs.androidx.navigation.compose)
    implementation(libs.androidx.activity.compose)
    implementation(platform(libs.androidx.compose.bom))
    implementation(libs.androidx.ui)
    implementation(libs.androidx.ui.graphics)
    implementation(libs.androidx.ui.tooling.preview)
    implementation(libs.androidx.material3)
    implementation(libs.androidx.material.icons.extended)

    // material-kolor：色阶生成。其 POM 会以 runtime scope 传递 JetBrains CMP 组件，
    // 且会把 material3 顶到 1.5.0-alpha17，与 BOM 的 foundation 1.12.0 错位，
    // 运行期触发 OutlinedTextFieldDefaults 内部 lambda 的 AbstractMethodError 闪退。
    // 故精确排除 CMP 传递依赖，material3/foundation 由显式声明接管。
    // 注意 exclude 的 group 是精确匹配，写前缀 org.jetbrains.compose 排不掉任何东西。
    implementation(libs.material.kolor) {
        exclude(group = "org.jetbrains.compose.material3")
        exclude(group = "org.jetbrains.compose.foundation")
        exclude(group = "org.jetbrains.compose.runtime")
        exclude(group = "org.jetbrains.compose.ui")
    }
    // ui-test-manifest 本地 Gradle 缓存未覆盖，且本项目暂无 instrumentation test，
    // 暂不引入，避免 --offline 构建失败。后续需要 UI 测试时再补 catalog 条目。
    debugImplementation(libs.androidx.ui.tooling)

    // APK 注入：dex 读写。只引这一个——
    //   apksig / apkzlib 曾评估过，最终未采用：
    //   · 不重签名 → apksig 用不上，且它 6 个类引用 java.util.stream（Android 上不存在）
    //   · apkzlib 的 bytestorage 引用 java.nio.file（Android 被裁剪），
    //     而 zip 读写用 java.util.zip 就够
    implementation(libs.smali.dexlib2)

    // 单元测试：注入核心（AXML / dex / 重打包）刻意不含 Android API，
    // 因此在本地 JVM（Termux）上就能跑真实 APK 的端到端验证，不必等真机。
    testImplementation("junit:junit:4.13.2")
    // Android 的 android.jar 在 JVM 单测里只是个壳：org.json 的每个方法都抛
    // "Method put in org.json.JSONObject not mocked"。表单 ↔ JSON 的往返
    // （插件包的核心契约）必须能离线验证，所以补一份真的实现。
    // 测试作用域，不进 APK。
    testImplementation("org.json:json:20240303")
}
